Deno.serve(async (req) => {
  const url = new URL(req.url);
  if (url.searchParams.get('k') !== SECRET) return new Response('no', { status: 401 });
  const sb = createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!);
  const log: string[] = [];
  for (const [id, secs] of Object.entries(DATA)) {
    const { data } = await sb.from('partners').select('product_filters,name').eq('id', id).maybeSingle();
    if (!data) { log.push(id + ' missing'); continue; }
    const pf: any = data.product_filters || {};
    for (const [k, sug] of Object.entries(secs)) {
      if (!pf[k] || typeof pf[k] !== 'object') continue;
      pf[k].deliveryProfile = { ...(pf[k].deliveryProfile || {}), suggestions: sug };
    }
    const { error } = await sb.from('partners').update({ product_filters: pf }).eq('id', id);
    log.push(data.name + (error ? ' ERR ' + error.message : ' ok'));
  }
  return new Response(JSON.stringify(log), { headers: { 'Content-Type': 'application/json' } });
});
